import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Documentation and development readiness","description":"Game design · Decisions · Start here","frontmatter":{"title":"Documentation and development readiness","description":"Game design · Decisions · Start here","source":"docs/planning/lesson-collection-delivery.md","category":"Delivery & team","sourceUpdated":"2026-11-11T13:03:58+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/planning/lesson-collection-delivery.md","filePath":"content/docs/planning/lesson-collection-delivery.md"}'),i={name:"content/docs/planning/lesson-collection-delivery.md"};function o(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<div><h1 id="documentation-and-development-readiness">Documentation and development readiness<a class="header-anchor" href="#documentation-and-development-readiness" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/project-baseline.html">Decisions</a> · <a href="/Chainy-Docs/content/docs/documentation-index.html">Start here</a></p><p><strong>Current phase: documentation and necessary setup only.</strong> The owner must give an explicit final decision before Unity development begins. An earlier execution directive does not override that boundary. Do not run implementation agents, modify the Unity project, create gameplay assets, or start builds while preparing these documents. <strong>Pre-final remains November 21, 2026.</strong> The actual November 10 session outcome remains unreported; no evaluation findings may be invented.</p><h2 id="what-must-be-ready-for-review">What must be ready for review<a class="header-anchor" href="#what-must-be-ready-for-review" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Deliverable</th><th>Concrete review material</th><th>Status</th></tr></thead><tbody><tr><td>Complete game design</td><td>39 ordered lessons, tutorial, exploration, encyclopedia, quest log, pause, world gates, nine distinct scene activities</td><td>Draft specified in the GDD</td></tr><tr><td>Lesson content</td><td>Exact term/source mapping, 39 panel meanings/examples, 39 four-choice questions and feedback</td><td>Authored draft; educator/source validation remains</td></tr><tr><td>Required quiz policy</td><td>13 questions per world, one per lesson; retry mistakes until all are correct</td><td>Owner confirmed; first-response evidence remains separate from corrected completion</td></tr><tr><td>Player flow and UI</td><td>Main menu through all worlds; locked, incomplete, saved, failure, retry, exit, pause and return states</td><td>Documented proposed behavior; visual approval remains</td></tr><tr><td>Architecture</td><td>Reuse existing Unity services, database bridge, scene/input systems; separate content, progress, activity rules, and UI</td><td>Proposed architecture, not implemented</td></tr><tr><td>Persistence contract</td><td>Atomic recording, prerequisite checkpoints, profile separation, version handling, failed-save recovery</td><td>Proposed contract, not implemented</td></tr><tr><td>Parallel workflow</td><td>Dependencies, exact file ownership, handoff artifacts, one integrator, test and merge gates</td><td>Prepared below; not executing</td></tr><tr><td>Documentation navigation</td><td>Five Essentials, All documents, Archive, consistent Obsidian Home/index</td><td>Validated locally; hosted status is recorded by the publication workflow</td></tr><tr><td>Board cleanup</td><td>Map existing cards to reuse, revise, superseded, or new requirements without resetting history</td><td>Complete: 36 active deliverables, 78 recoverable archives, six additions; dependencies and date order verified</td></tr><tr><td>Development authorization</td><td>Owner reviews the documentation and explicitly approves starting Unity work</td><td><strong>Not granted</strong></td></tr></tbody></table><p>Design readiness, educational validation, toolchain readiness, and implemented/tested behavior are different states. Do not turn a documentation checkbox into a claim of a working game. Do not estimate delivery from token capacity, task counts, or assumed human availability.</p><h2 id="current-audit-facts-and-setup-limits">Current audit facts and setup limits<a class="header-anchor" href="#current-audit-facts-and-setup-limits" aria-label="Link to this section">​</a></h2><p>The prior read-only/source audit identified Unity 6000.3.25f1, Plastic changeset 185, and existing movement, dialogue, SQLite, profile, encyclopedia, quest UI, and Wordle code. All 57 pre-existing Wordle EditMode tests passed during the premature development attempt. No new gameplay implementation was completed. The new contracts/stubs/tests introduced during that attempt were removed after the owner clarified the boundary. No scenes, prefabs, existing gameplay source, or build configuration were changed by that attempt.</p><p>The Unity CLI was installed locally during setup. Android Build Support was absent at audit; its installation was started and then cancelled. Do not mark the Android toolchain ready or claim an APK was produced. The standalone .NET test instructions referenced missing project files and no usable SDK; record this for the later tooling packet. No phone/emulator acceptance, Android performance result, or November 10 evaluation result has been established. Further Unity inspection, repair, installation, builds, and runtime checks wait for final approval.</p><h2 id="proposed-system-architecture">Proposed system architecture<a class="header-anchor" href="#proposed-system-architecture" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart LR
  C[Reviewed lesson and activity content] --&gt; R[Ordered progress service]
  C --&gt; A[Nine distinct activity rules]
  UI[Views and input handlers] --&gt; R
  UI --&gt; A
  A --&gt; H[Validated completion handoff]
  H --&gt; R
  R --&gt; DB[Existing SQLite bridge and atomic checkpoint]
  DB --&gt; E[Saved encyclopedia and quest state]
  E --&gt; UI
  R --&gt; G[World and required-quiz gates]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>Use the <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a> and <a href="/Chainy-Docs/content/docs/design/database-schema.html">data contract</a> for the proposed interfaces and failure behavior. Keep a single authority for recorded lessons and encyclopedia completion; two independent saves must not disagree. Content definitions are immutable during play, while per-profile progress belongs in SQLite. Activity rules decide success; UI buttons cannot award a lesson directly. A saved required-review result unlocks the next world. The offline game has no currently required networking endpoint. Teacher services, vouchers, dashboards, exports, and standalone Wordle/BlockMatch are outside this scope, with their old tasks retained in the archive.</p><h2 id="future-agent-execution-after-approval">Future agent execution, after approval<a class="header-anchor" href="#future-agent-execution-after-approval" aria-label="Link to this section">​</a></h2><p>One coordinator maintains the dependency graph, contracts, review queue, and integration evidence. Use no more than three isolated workers at a time alongside the coordinator. Explain why each independent workstream benefits from a separate worker before dispatching it. A worker receives only its objective, authoritative inputs, allowed files, expected outputs, edge cases, and verification commands.</p><table><thead><tr><th>Packet</th><th>Proposed file boundary in game checkout</th><th>Prerequisites</th><th>Required evidence</th></tr></thead><tbody><tr><td>A. Audit and baseline</td><td>Read-only source/history first; approved build/test configuration changes afterward</td><td>Explicit final approval</td><td>Reproducible baseline, exact failures, actual Android toolchain status</td></tr><tr><td>B. Content definitions</td><td>New lesson-content definitions and reviewed content assets; no scene or persistence edits</td><td>A and reviewed content schema</td><td>All 39 IDs, nine activity assignments, source mapping, valid question keys</td></tr><tr><td>C. Progress and persistence</td><td>Isolated progress feature and its tests; shared schema changes go through coordinator</td><td>A and frozen state contract</td><td>Red then green checks for order, tutorial, prerequisite steps, atomic saves, duplicate events, restart and profiles</td></tr><tr><td>D. Activity rules</td><td>Isolated nine activity modules and tests; no progress/storage/UI mutations</td><td>A and approved minigame rules</td><td>Each distinctive success rule, mistakes, corrections, reset and invalid actions tested</td></tr><tr><td>E. UI and encounters</td><td>Approved views/handlers and serialized UI configuration</td><td>B/C/D interfaces stable</td><td>Joystick/overlays, lesson targets, sequence, encyclopedia, quiz, save-error recovery</td></tr><tr><td>F. Shared integration</td><td>Scene/prefab wiring, identifiers, shared configuration, migrations, build settings</td><td>Accepted B/C/D/E outputs</td><td>One coherent flow and full regression after each integrated increment</td></tr><tr><td>G. Android acceptance and handover</td><td>Build artifacts and evidence records</td><td>F</td><td>Named APK, install, offline journey, logs, restart, device checks, limitations</td></tr></tbody></table><p>Proposed paths are boundaries to verify during packet A, not files to create during preparation. Reuse existing systems where they satisfy the contract; do not replace working services solely to match the proposal. Never let two workers mutate the same scene, prefab, schema, or shared configuration concurrently. The coordinator integrates one accepted increment at a time and rejects unverified output. A missing SDK/module is an environment issue to resolve after approval, not a reason to report tests as passed.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  Approval[Owner final approval] --&gt; A[Audit and baseline]
  A --&gt; B[Content definitions]
  A --&gt; C[Progress and persistence]
  A --&gt; D[Activity rules]
  B --&gt; E[UI and encounters]
  C --&gt; E
  D --&gt; E
  E --&gt; F[Sequential shared integration]
  F --&gt; G[Android acceptance and evidence]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><h2 id="human-ownership-and-board-preparation">Human ownership and board preparation<a class="header-anchor" href="#human-ownership-and-board-preparation" aria-label="Link to this section">​</a></h2><p>Keep the established human lanes: Sherwin for coordination/design, Christian for code/data/builds, Luis for art, Sean for authored documentation, and Miguel for UI. Agents can execute an approved packet without becoming board accounts or changing those named responsibilities. Use explicit handoffs between lanes and one owner per card.</p><p>Before editing the board, inspect its live cards and map them to the approved outcomes. Reuse matching cards and preserve their IDs, status, owners, audit history, and evidence. The owner authorized rebaselining unfinished dates after this documentation review. Keep completed dates unchanged and label future implementation dates as conditional planning targets, not start authorization or delivery promises. Move obsolete economy requirements to a recoverable superseded/archive state through the board. Do not independently rewrite managed GitHub issue bodies or edit <code>backlog.json</code> as a second board. Do not create dozens of speculative subtasks while the design is still under review.</p><h2 id="final-approval-gate">Final approval gate<a class="header-anchor" href="#final-approval-gate" aria-label="Link to this section">​</a></h2><p>Present the current GDD, its nine minigame rules, lesson/quiz content, proposed architecture, known setup gaps, and this execution workflow together for review. Review visual/content proposals and record accepted assumptions; the quiz policy is already confirmed. Only a clear owner instruction to start development opens packet A and subsequent Unity work. Silence, elapsed time, available agents, a passing documentation build, or an earlier contradictory directive does not grant approval.</p></div>`,1)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
